package org.zhixiaoce.aperture;

public final class GalleryTraceTest {
    static int n;static void ok(boolean v,String label){if(!v)throw new AssertionError(label);n++;}
    static final class Clock implements PageDeadline.Clock,PageDeadline.Scheduler{long now;Runnable job;public long now(){return now;}public void post(Runnable r,long delay){job=r;}public void cancel(Runnable r){if(job==r)job=null;}}
    public static void main(String[] args){
        Clock c=new Clock();int[] expires={0};PageDeadline d=new PageDeadline(100,c,c,t->expires[0]++);PageDeadline.Ticket t=d.start(new Object());
        ok(!d.snapshot().armed&&d.snapshot().dueAt==-1,"inactive start is not an armed deadline");d.active(true);ok(d.snapshot().armed&&d.snapshot().dueAt==100,"actual arm due recorded");c.now=30;ok(d.snapshot().remaining==70,"foreground remaining budget");
        d.active(false);ok(!d.snapshot().armed&&d.snapshot().dueAt==-1&&d.snapshot().remaining==70,"pause removes scheduled due while retaining budget");c.now=5000;ok(d.snapshot().delay==0&&d.snapshot().callbackAt==-1,"pause time is not callback delay");d.active(true);ok(d.snapshot().dueAt==5070,"resume arms only remaining budget");d.ready(t);ok(!d.snapshot().armed&&d.snapshot().dueAt==-1,"ready is unarmed");c.now=20000;ok(d.snapshot().delay==0,"ready time is not growing scheduling delay");
        d.start(new Object());Runnable cancelled=c.job;d.cancel();c.now=50000;ok(!d.snapshot().armed&&d.snapshot().dueAt==-1&&d.snapshot().delay==0,"cancel has no stale scheduled deadline or delay");cancelled.run();ok(expires[0]==0,"cancelled callback cannot expire");
        c.now=0;d.start(new Object());Runnable expired=c.job;c.now=150;expired.run();PageDeadline.Snapshot actual=d.snapshot();ok(expires[0]==1&&actual.callbackDueAt==100&&actual.callbackAt==150&&actual.delay==50,"callback records actual dispatch delay");ok(!actual.armed&&actual.dueAt==-1&&actual.remaining==0,"expired deadline no longer armed");c.now=10000;ok(d.snapshot().delay==50&&d.snapshot().callbackAt==150,"recorded delay is immutable as time advances");d.cancel();ok(d.snapshot().delay==50&&!d.snapshot().armed,"cancel preserves labelled historical callback measurement only");PageDeadline.Ticket newer=d.start(new Object());ok(d.snapshot().callbackAt==-1&&d.snapshot().delay==0,"new generation clears previous callback measurement");expired.run();ok(d.waiting(newer)&&expires[0]==1,"old callback cannot change new generation");
        ok(GalleryTrace.asset("/api/gallery")==GalleryTrace.Asset.API,"API category");ok(GalleryTrace.asset("/gallery/photos/SYNTHETIC_PRIVATE.jpg")==GalleryTrace.Asset.PHOTO,"photo names reduced to category");ok(GalleryTrace.asset("/private?token=SYNTHETIC")==GalleryTrace.Asset.OTHER,"unknown path reduced to category");ok(GalleryTrace.console("Uncaught SyntaxError: SYNTHETIC_URL")==GalleryTrace.Result.SYNTAX_ERROR,"console parse class only");ok(GalleryTrace.console("secret user text")==GalleryTrace.Result.OTHER_ERROR,"arbitrary console text cannot enter trace vocabulary");
        GalleryTrace trace=new GalleryTrace();for(int i=0;i<500;i++)trace.add(new GalleryTrace.Entry(GalleryTrace.Stage.FOCUS,GalleryTrace.Asset.NONE,GalleryTrace.Result.NONE,1,i,null,true,true,false,0));ok(trace.snapshot().size()==160,"trace ring bounded");trace.snapshot().clear();ok(trace.snapshot().size()==160,"snapshot cannot mutate journal");
        trace=new GalleryTrace();int recorded=0;for(int i=0;i<50;i++)if(trace.add(new GalleryTrace.Entry(GalleryTrace.Stage.RESOURCE_HIT,GalleryTrace.Asset.PHOTO,GalleryTrace.Result.NONE,1,i,null,true,true,false,0)))recorded++;ok(recorded==3,"success resource spam limited by category");GalleryTrace.Entry e=new GalleryTrace.Entry(GalleryTrace.Stage.CONSOLE,GalleryTrace.Asset.OTHER,GalleryTrace.Result.TYPE_ERROR,1,0,null,true,false,false,Integer.MAX_VALUE);trace.add(e);ok(e.line==1000000&&e.callbackAt==-1&&!e.armed,"line bounds and unknown budget explicit");
        System.out.println("GalleryTrace: "+n+" model checks passed; no Android/WebView executed");
    }
}
